import re
import pandas as pd
file_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/54612da3-fd56-4941-80f4-5eb82330de25.xlsx"
df = pd.read_excel(file_path)

contrib = []

def wheels_from_cell(cell):
    if pd.isna(cell):
        return None
    s = str(cell)
    nums = re.findall(r"\d+", s)
    if '-' in s and len(nums) >= 3:
        # sum first three numbers
        return sum(map(int, nums[:3]))
    elif len(nums) == 1:
        # treat single numeric token as a wheel count indicator
        return int(nums[0])
    else:
        return None

for idx, row in df.iterrows():
    w = wheels_from_cell(row['Type/Wheel Configuration'])
    if w is not None:
        contrib.append((idx, row['Number'], row['Type/Wheel Configuration'], w))

alt_total = sum(w for (_,_,_,w) in contrib)
print("Cross-check contributions:")
for item in contrib:
    print(item)
print("Alternate total (all rows numeric parse):", alt_total)
